/// <summary>
///    AVA <c>setButtonFollowup</c> method.
/// </summary>
protected void setButtonFollowup()
{
    next setButtonFollowup();

    this.listPage().actionPaneControlEnabled(formControlStr(SalesQuotationListPage, AVAbuttonCopyAllFirst), salesQuotationTableInteractionHelper.parmMayQuotationBeCopied());
    //this.listPage().actionPaneControlEnabled(formControlStr(SalesQuotationListPage, AVAbuttonCopyAllJour), salesQuotationTableInteractionHelper.parmMayQuotationBeCopied());

    salesQuotationTable     sqt = this.listPage().activeRecord(queryDataSourceStr(SalesQuotationListPage, SalesQuotationTable)) as SalesQuotationTable;
    boolean                 posExists = SalesQuotationLine::exist(sqt.QuotationId);
    this.listPage().actionPaneControlEnabled(formControlStr(SalesQuotationListPage, AVAbuttonCopyAllJour), posExists);
    this.listPage().actionPaneControlEnabled(formControlStr(SalesQuotationListPage, AVASalesQuotationQuickCopying), !posExists);
    this.listPage().actionPaneControlEnabled(formControlStr(SalesQuotationListPage, AVASalesQuotationQuickCopyingCross), !posExists);
}

/// <summary>
///    AVA <c>setButtonQuote</c> method.
/// </summary>
protected void setButtonQuote()
{
    next setButtonQuote();

    //salesQuotationTable     sqt = this.listPage().activeRecord(queryDataSourceStr(SalesQuotationListPage, SalesQuotationTable)) as SalesQuotationTable;
    /*boolean                 isGAEB = sqt.KCS_GAEBImportID && SalesQuotationLine::exist(sqt.QuotationId);
    this.listPage().actionPaneControlEnabled(formControlStr(SalesQuotationListPage, AVAGAEBExportD94), isGAEB);*/
    /*this.listPage().actionPaneControlEnabled(formControlStr(SalesQuotationListPage, AVAUpdateQuotation), isSalesQuotationVisible && salesQuotationTableInteractionHelper.parmUpdateQuotationEnabled());*/
    this.listPage().actionPaneControlEnabled(formControlStr(SalesQuotationListPage, AVAUpdateQuotation), true);
    this.listPage().actionPaneControlVisible(formControlStr(SalesQuotationListPage, updateQuotation), false);
    this.listPage().actionPaneControlEnabled(formControlStr(SalesQuotationListPage, AVAMailAgain), salesQuotationTableInteractionHelper.parmJournalQuotationEnabled());

    // Accounts
    this.listPage().actionPaneControlEnabled(formControlStr(SalesQuotationListPage, AVACustomer), salesQuotationTable && salesQuotationTable.CustAccount != "");
    this.listPage().actionPaneControlEnabled(formControlStr(SalesQuotationListPage, AVABusinessRelationship), isRelAccountValid);
    this.listPage().actionPaneControlEnabled(formControlStr(SalesQuotationListPage, AVAContactPerson), salesQuotationTableInteractionHelper.parmIsNotTemplate());

    // Journals group
    this.listPage().actionPaneControlEnabled(formControlStr(SalesQuotationListPage, AVAQuotationJournalsAll), salesQuotationTableInteractionHelper.parmJournalQuotationEnabled());

    // Related information
    this.listPage().actionPaneControlVisible(formControlStr(SalesQuotationListPage, CreateActivity), false);
}
